<?php declare(strict_types=1);require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('payments.view');$status=strtoupper(trim((string)input('status')));$provider=strtoupper(trim((string)input('provider')));$where=[];$params=[];if(in_array($status,['CREATED','PENDING','VERIFIED','FAILED','REFUNDED'],true)){$where[]='p.status=?';$params[]=$status;}if(in_array($provider,['RAZORPAY','PHONEPE','COUNTER'],true)){$where[]='p.provider=?';$params[]=$provider;}$s=db()->prepare('SELECT p.*,u.name user_name,u.mobile,h.title hunt_title FROM payment_transactions p JOIN users u ON u.id=p.user_id JOIN hunts h ON h.id=p.hunt_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY p.id DESC LIMIT 300');$s->execute($params);$items=$s->fetchAll();$pageTitle='Hunt payments';$pageSubtitle='Server-created orders and signature-verified provider outcomes';require APP_ROOT.'/includes/header.php';?><section class="panel"><form method="get" class="filters"><select name="provider"><option value="">All providers</option><?php foreach(['RAZORPAY','PHONEPE','COUNTER'] as $v):?><option <?=$provider===$v?'selected':''?>><?=e($v)?></option><?php endforeach?></select><select name="status"><option value="">All statuses</option><?php foreach(['CREATED','PENDING','VERIFIED','FAILED','REFUNDED'] as $v):?><option <?=$status===$v?'selected':''?>><?=e($v)?></option><?php endforeach?></select><button class="btn">Filter</button></form><div class="table-wrap"><table><thead><tr><th>Payment</th><th>User</th><th>Hunt</th><th>Provider</th><th>Order / payment refs</th><th>Amount</th><th>Status</th><th>Verified</th></tr></thead><tbody><?php foreach($items as $p):?><tr><td><?=e($p['payment_id'])?><br><small><?=e($p['created_at'])?></small></td><td><?=e($p['user_name'])?><br><small><?=e($p['mobile'])?></small></td><td><?=e($p['hunt_title'])?></td><td><?=e($p['provider'])?></td><td><?=e($p['provider_order_id']??'—')?><br><?=e($p['provider_payment_id']??'—')?></td><td><?=money($p['amount'])?></td><td><span class="badge <?=strtolower(e($p['status']))?>"><?=e($p['status'])?></span></td><td><?=e($p['signature_verified_at']??'—')?></td></tr><?php endforeach?></tbody></table><?php if(!$items):?><div class="empty">No payments match these filters.</div><?php endif?></div></section><?php require APP_ROOT.'/includes/footer.php';
